                        <line x1="0" y1="480" x2="1900" y2="480" stroke="#e2e8f0" stroke-width="2"/>

                        <!-- Pre-pandemic average (3.8%) -->
                        <line x1="0" y1="64" x2="1900" y2="64" stroke="#64748b" stroke-width="6" stroke-dasharray="16, 16"/>

                        <!-- The Growth Band Path -->
                        <path d="M 0 256 L 271 256 L 542 224 L 814 272 L 1085 320 L 1357 288 L 1628 224 L 1900 288" 
                              fill="none" stroke="#002244" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/>

                        <!-- Data Points -->
                        <circle cx="0" cy="256" r="14" fill="#d97706" />
                        <circle cx="271" cy="256" r="14" fill="#d97706" />
                        <circle cx="542" cy="224" r="14" fill="#d97706" />
                        <circle cx="814" cy="272" r="14" fill="#d97706" />
                        <circle cx="1085" cy="320" r="14" fill="#d97706" />
                        <circle cx="1357" cy="288" r="14" fill="#d97706" />
                        <circle cx="1628" cy="224" r="14" fill="#d97706" />
                        <circle cx="1900" cy="288" r="14" fill="#d97706" />

                        <!-- Labels on points -->
                        <text x="0" y="220" font-size="28" font-weight="bold" fill="#002244">3.2%</text>
                        <text x="271" y="220" font-size="28" font-weight="bold" fill="#002244">3.2%</text>
                        <text x="542" y="188" font-size="28" font-weight="bold" fill="#002244">3.3%</text>
                        <text x="814" y="315" font-size="28" font-weight="bold" fill="#002244">~3.2%</text>
