                        <text x="1628" y="188" font-size="28" font-weight="bold" fill="#002244">3.3%</text>
                        <text x="1840" y="330" font-size="28" font-weight="bold" fill="#002244">~3.1%</text>
                    </svg>
                </div>
                <div class="chart-labels" style="padding-left: 80px;">
                    <span>Jul '24</span>
                    <span>Oct '24</span>
                    <span>Jan '25</span>
                    <span>Apr '25</span>
                    <span>Jul '25</span>
