                    </div>
                </div>
                <div class="timeline-item">
                    <div class="timeline-dot"></div>
                    <div class="timeline-content">
                        <div class="timeline-date">Early 2026</div>
                        <p class="text-body" style="font-size: 28px; color: #d97706; font-weight: 600;">Agile policy is paramount. Manage defense-spending trade-offs and lay foundations for recovery amidst the "Shadow of War."</p>
                    </div>
                </div>
            </div>

            <h2 class="card-title" style="margin-top: 40px;">Thematic Focus Areas</h2>
            <div class="text-body">
                <p>Special analytical chapters shifted from traditional stabilization toward inclusive growth:</p>
                <ul>
                    <li>Monetary policy's role in disinflation.</li>
                    <li>Social acceptability of structural reforms.</li>
                    <li>Effectiveness and fiscal cost of industrial policy.</li>
                    <li>Addressing aging populations, gender disparities, and migrant skill alignment.</li>
                </ul>
            </div>
        </div>

    </div>

</body>
</html>"""

async def generate():
    with open("poster.html", "w", encoding="utf-8") as f:
        f.write(html_content)

    async with async_playwright() as p:
        # Launch browser without sandbox if running as root in docker
        browser = await p.chromium.launch(args=['--no-sandbox', '--disable-setuid-sandbox'])
        page = await browser.new_page(viewport={'width': 2480, 'height': 3508})

        abs_path = "file://" + os.path.abspath("poster.html")
        await page.goto(abs_path, wait_until="networkidle")

        # Ensure fonts and elements are fully rendered
        await page.wait_for_timeout(2000)

        os.makedirs("/app/output", exist_ok=True)
        await page.screenshot(path="/app/output/final_poster.png", full_page=True)
        await browser.close()

if __name__ == "__main__":
    asyncio.run(generate())
